const rawOutput = $input.first().json.message?.content || '{}';
try {
  const parsed = JSON.parse(rawOutput.replace(/```json|```/g, '').trim());
  return {
    json: {
      ...parsed,
      userName: $('Webhook Lead Event').first().json.body.userName,
      senderPhone: $('Webhook Lead Event').first().json.body.senderPhone,
      timestamp: new Date().toISOString()
    }
  };
} catch (e) {
  return {
    json: {
      leadScore: 50,
      buyingIntent: 'WARM',
      summary: 'Conversa em andamento',
      needsHumanHandover: false
    }
  };
}
